import { ComponentType, ReactNode } from 'react';

export function compose(providers: ComponentType<{ children: ReactNode }>[]) {
  return ({ children }: { children: ReactNode }) =>
    providers.reduceRight((acc, P) => <P>{acc}</P>, children as ReactNode);
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  return <div data-theme="dark">{children}</div>;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  return <div lang="en">{children}</div>;
}

export const AppProviders = compose([ThemeProvider, I18nProvider]);
